CREATE TABLE `user`(user_id INT PRIMARY KEY,email VARCHAR(100),password VARCHAR(255),name VARCHAR(50),nickname VARCHAR(50),role VARCHAR(20),status VARCHAR(20),email_verified_at TIMESTAMP,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP,scheduled_delete_at TIMESTAMP);
CREATE TABLE no_smoking_record(no_smoking_record_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,start_date TIMESTAMP NOT NULL,end_date TIMESTAMP,status VARCHAR(20) DEFAULT 'IN_PROGRESS',daily_cigarettes INT NOT NULL,cigarette_price INT NOT NULL,cigarettes_per_pack INT DEFAULT 20,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE no_smoking_attendance(attendance_id INT AUTO_INCREMENT PRIMARY KEY,no_smoking_record_id INT,attendance_date DATE,reward_points INT,created_at TIMESTAMP,UNIQUE(no_smoking_record_id,attendance_date));
CREATE TABLE no_smoking_tree(tree_id INT AUTO_INCREMENT PRIMARY KEY,no_smoking_record_id INT UNIQUE,growth_rate INT DEFAULT 0,water_count INT DEFAULT 0,fertilizer_count INT DEFAULT 0,is_fully_grown BOOLEAN DEFAULT FALSE,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE no_smoking_travel(no_smoking_travel_id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(100),description VARCHAR(255),required_minutes INT,reward_points INT,travel_order INT,created_at TIMESTAMP);
CREATE TABLE no_smoking_travel_progress(travel_progress_id INT AUTO_INCREMENT PRIMARY KEY,no_smoking_record_id INT,no_smoking_travel_id INT,achieved_at TIMESTAMP,created_at TIMESTAMP,UNIQUE(no_smoking_record_id,no_smoking_travel_id));
CREATE TABLE `point`(point_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,amount INT,point_type VARCHAR(30),description VARCHAR(255),granted_by INT,created_at TIMESTAMP);
CREATE TABLE activity_record(activity_record_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,activity_type VARCHAR(50),target_id INT,description VARCHAR(255),created_at TIMESTAMP);
CREATE TABLE notification(notification_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,notification_type VARCHAR(30),content VARCHAR(255),is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP,read_at TIMESTAMP);
CREATE TABLE wishlist(wishlist_id INT AUTO_INCREMENT PRIMARY KEY,no_smoking_record_id INT,item_name VARCHAR(100),target_price INT,status VARCHAR(20) DEFAULT 'IN_PROGRESS',achieved_at TIMESTAMP,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE fighting(fighting_id INT AUTO_INCREMENT PRIMARY KEY,content VARCHAR(500),is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP);
CREATE TABLE post(post_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT,title VARCHAR(200),content TEXT,view_count INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE `comment`(comment_id INT AUTO_INCREMENT PRIMARY KEY,post_id INT,user_id INT,parent_comment_id INT,content TEXT,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE post_image(image_id INT AUTO_INCREMENT PRIMARY KEY,post_id INT,image_url VARCHAR(500),image_order INT,created_at TIMESTAMP);
CREATE TABLE post_like(like_id INT AUTO_INCREMENT PRIMARY KEY,post_id INT,user_id INT,created_at TIMESTAMP,UNIQUE(post_id,user_id));
CREATE TABLE report(report_id INT AUTO_INCREMENT PRIMARY KEY,reporter_id INT,target_type VARCHAR(20),target_id INT,reason VARCHAR(255),status VARCHAR(20) DEFAULT 'PENDING',processed_at TIMESTAMP,processed_by INT,created_at TIMESTAMP,UNIQUE(reporter_id,target_type,target_id));
